    t[3901] = "Acceso a Informaci\u00f3n Personal";
    t[3906] = "use cookies, cookies are data that a Web site transfers to an individual\u2019s hard drive for record-keeping purposes. Cookies can facilitate a user\u2019s ongoing access to and use of a site. They allow us to track usage patterns and to compile data that can help us improve our content and target advertising. If you do not want information collected through the use of Cookies, there is a simple procedure in most browsers that allows you to deny or accept the Cookie feature. But you should note that Cookies may be necessary to provide you with features such as merchandise transactions or registered services";
    t[3907] = "utilizar cookies, las cookies son informaci\u00f3n que un sitio Web transfiere a su disco duro para prop\u00f3sitos de seguimiento. Las cookies facilitan a un usuario el acceso y utilizaci\u00f3n de un sitio. Nos permiten identificar el uso de patrones y la informaci\u00f3n recolectada nos ayuda a mejorar nuestro contenido y anuncios. Si usted no quiere que su informaci\u00f3n sea recolectada con cookies, hay un procedimiento simple en la mayor\u00eda de los navegadores que le permite negar el acceso a  las cookies. Pero debe tomar en cuenta que puede ser que las cookies sean necesarias para proveerle con caracter\u00edsticas tales como transacciones en l\u00ednea o servicios registrados";
